func PrintDefsUses(fset *token.FileSet, files ...*ast.File) error {
	conf := types.Config{Importer: importer.Default()}
	info := &types.Info{
		Defs: make(map[*ast.Ident]types.Object),
		Uses: make(map[*ast.Ident]types.Object),
	}
	_, err := conf.Check("hello", fset, files, info)
	if err != nil {
		return err // type error
	}

	for id, obj := range info.Defs {
		fmt.Printf("%s: %q defines %v\n",
			fset.Position(id.Pos()), id.Name, obj)
	}
	for id, obj := range info.Uses {
		fmt.Printf("%s: %q uses %v\n",
			fset.Position(id.Pos()), id.Name, obj)
	}
	return nil
}

function detect(value: unknown): TypeName {
	if (value === null) {
		return 'null';
	}

	// eslint-disable-next-line @typescript-eslint/switch-exhaustiveness-check
	switch (typeof value) {
		case 'undefined': {
			return 'undefined';
		}

		case 'string': {
			return 'string';
		}

		case 'number': {
			return Number.isNaN(value) ? 'NaN' : 'number';
		}

		case 'boolean': {
			return 'boolean';
		}

		case 'function': {
			return 'Function';
		}

		case 'bigint': {
			return 'bigint';
		}

		case 'symbol': {
			return 'symbol';
		}

		default:
	}

	if (isObservable(value)) {
		return 'Observable';
	}

	if (isArray(value)) {
		return 'Array';
	}

	if (isBuffer(value)) {
		return 'Buffer';
	}

	const tagType = getObjectType(value);
	if (tagType !== undefined && tagType !== 'Object') {
		return tagType;
	}

	if (hasPromiseApi(value)) {
		return 'Promise';
	}

	if (isBoxedPrimitiveObject(value)) {
		throw new TypeError('Please don\'t use object wrappers for primitive types');
	}

	return 'Object';
}

export function isEmptyStringOrWhitespace(value: unknown): value is '' | Whitespace {
	return isEmptyString(value) || isWhitespaceString(value);
}

export function isAll(predicate: Predicate | readonly Predicate[], ...values: unknown[]): boolean | Predicate {
	if (Array.isArray(predicate)) {
		const predicateArray = predicate as readonly Predicate[];
		validatePredicateArray(predicateArray, values.length === 0);

		const combinedPredicate = (value: unknown) => predicateArray.every(singlePredicate => singlePredicate(value));
		if (values.length === 0) {
			return combinedPredicate;
		}

		return predicateOnArray(Array.prototype.every, combinedPredicate, values);
	}

	return predicateOnArray(Array.prototype.every, predicate as Predicate, values);
}

function isAbsoluteModule2(remainder: 0 | 1) {
	return (value: unknown): value is number => isInteger(value) && Math.abs(value % 2) === remainder;
}

class HMACAlgorithm(SigningAlgorithm):
    """Provides signature generation using HMACs."""

    #: The digest method to use with the MAC algorithm. This defaults to
    #: SHA1, but can be changed to any other function in the hashlib
    #: module.
    default_digest_method: t.Any = staticmethod(_lazy_sha1)

    def __init__(self, digest_method: t.Any = None):
        if digest_method is None:
            digest_method = self.default_digest_method

        self.digest_method: t.Any = digest_method

    def get_signature(self, key: bytes, value: bytes) -> bytes:
        mac = hmac.new(key, msg=value, digestmod=self.digest_method)
        return mac.digest()

def want_bytes(
    s: str | bytes, encoding: str = "utf-8", errors: str = "strict"
) -> bytes:
    if isinstance(s, str):
        s = s.encode(encoding, errors)

    return s
